<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarMuestra, guardarMuestra, listarMuestras } from '../services/muestras'
import type { MuestraAgua, MuestraPayload, OpcionMuestra } from '../interfaces/muestras.interface'
const records=ref<MuestraAgua[]>([]),components=ref<OpcionMuestra[]>([]),responsibles=ref<OpcionMuestra[]>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),filters=reactive({criterio:'',fecha_desde:'',fecha_hasta:''}),totals=reactive({mes:0,con_resultados:0,pendientes:0}),form=reactive<MuestraPayload>({componente_id:null,fecha:'',hora:'',direccion:'',latitud:null,longitud:null,observacion:'',responsable_id:null})
async function load(target=1){loading.value=true;error.value='';try{const r=await listarMuestras({...filters,page:target});records.value=r.data;components.value=r.componentes;responsibles.value=r.responsables;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;Object.assign(totals,r.totales)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',fecha_desde:'',fecha_hasta:''});load(1)}
function open(item?:MuestraAgua){editing.value=item?.id??null;const now=new Date();Object.assign(form,item?{componente_id:item.componente_id,fecha:item.fecha,hora:item.hora.slice(0,5),direccion:item.direccion,latitud:item.latitud,longitud:item.longitud,observacion:item.observacion,responsable_id:item.responsable_id}:{componente_id:null,fecha:now.toISOString().slice(0,10),hora:now.toTimeString().slice(0,5),direccion:'',latitud:null,longitud:null,observacion:'',responsable_id:null});modal.value=true}
async function save(){if(!form.componente_id||!form.fecha||!form.hora||!form.direccion.trim()||!form.observacion.trim()||!form.responsable_id){error.value='Complete todos los campos obligatorios.';return}saving.value=true;error.value='';try{await guardarMuestra({...form,direccion:form.direccion.trim(),observacion:form.observacion.trim()},editing.value??undefined);modal.value=false;success.value=`Muestra ${editing.value?'actualizada':'registrada'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:MuestraAgua){if(item.resultados_count){error.value='No se puede eliminar porque la muestra tiene resultados registrados.';return}if(!confirm(`¿Eliminar la muestra #${item.id}?`))return;try{await eliminarMuestra(item.id);success.value='Muestra eliminada correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Control de Calidad / Muestras</nav><header class="hero"><div class="mark">MA</div><div><small>DANA · CONTROL DE CALIDAD</small><h1>Muestras de agua</h1><p>Programa y registra la toma de muestras en componentes operacionales.</p></div><button @click="open()">+ Nueva muestra</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>TOTAL MUESTRAS</small><b>{{total}}</b></article><article><small>DEL MES</small><b>{{totals.mes}}</b></article><article><small>CON RESULTADOS</small><b>{{totals.con_resultados}}</b></article><article class="warning"><small>PENDIENTES DE RESULTADOS</small><b>{{totals.pendientes}}</b></article></section><form class="filters" @submit.prevent="load(1)"><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><label class="search">Buscar<input v-model.trim="filters.criterio" placeholder="Dirección, fecha, hora u observación"></label><div><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></div></form><div v-if="loading" class="empty">Cargando muestras…</div><div v-else-if="!records.length" class="empty">No se encontraron muestras.</div><section v-else class="cards"><article v-for="item in records" :key="item.id"><header><div class="flask">⚗</div><div><small>MUESTRA N.° {{item.id}}</small><h2>{{item.fecha}} · {{item.hora.slice(0,5)}}</h2></div><span>{{item.resultados_count}} resultado(s)</span></header><div class="location"><b>{{item.localidad||'Localidad no registrada'}}</b><span>{{item.direccion}}</span></div><dl><div><dt>Componente</dt><dd>{{item.componente}}</dd></div><div><dt>Periodicidad</dt><dd>{{item.periodicidad||'—'}}</dd></div><div><dt>Periodo</dt><dd>{{item.anio}} - {{String(item.mes).padStart(2,'0')}}</dd></div><div><dt>Responsable</dt><dd>{{item.responsable||'—'}}</dd></div></dl><p>{{item.observacion}}</p><footer><button class="results">Resultados</button><button class="edit" @click="open(item)">Modificar</button><button class="delete" :disabled="!!item.resultados_count" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>CONTROL DE CALIDAD</small><h2>{{editing?'Modificar':'Registrar'}} muestra de agua</h2></div><button type="button" @click="modal=false">×</button></header><div class="fields"><label class="wide">Componente sujeto a control *<select v-model="form.componente_id" required><option :value="null">Seleccione</option><option v-for="item in components" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Fecha *<input v-model="form.fecha" type="date" required></label><label>Hora *<input v-model="form.hora" type="time" required></label><label class="wide">Dirección *<input v-model="form.direccion" maxlength="100" required></label><label>Latitud<input v-model.number="form.latitud" type="number" step="any" placeholder="Opcional"></label><label>Longitud<input v-model.number="form.longitud" type="number" step="any" placeholder="Opcional"></label><label class="wide">Observación *<textarea v-model="form.observacion" rows="3" maxlength="100" required></textarea><span>{{form.observacion.length}} / 100</span></label><label class="wide">Responsable *<select v-model="form.responsable_id" required><option :value="null">Seleccione responsable</option><option v-for="item in responsibles" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Guardar cambios':'Registrar muestra'}}</button></footer></form></div></div></template>
